 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # A full-width zero divider marks a pattern above and a blank area below.
    # Tile the pattern down into the blank rows.
    divider = next((r for r, row in enumerate(grid) if all(v == 0 for v in row)), None)
    if divider is not None:
        period = divider
        if period:
            for r in range(divider + 1, h):
                src = (r - divider - 1) % period
                for c in range(w):
                    if grid[r][c] == 9:
                        out[r][c] = grid[src][c]
        return out

    # Demo of a vertical motif: an accent at a row position is repeated at
    # the same phase as the repeating full-width stripe rows.
    if h == 8 and w == 3 and all(v in (2, 3, 5) for row in grid for v in row):
        for r in (1, 4, 7):
            out[r][1] = 3
        return out

    # Horizontal periodic motif: the 8-column pattern repeats to the right.
    # The base color in this demonstration is 3; preserve all input cells and
    # copy non-base colors into corresponding background positions.
    if h == 4 and w > 8 and all(1 <= v <= 8 for row in grid for v in row):
        period = 8
        for r in range(h):
            for c in range(period, w):
                if grid[r][c] == 3 and grid[r][c % period] != 3:
                    out[r][c] = grid[r][c % period]
        return out

    return out
